      "p.cuerpo.luna": "Moon",
      "p.cuerpo.marte": "Mars",
      "p.cuerpo.espacio": "Deep space",
      "p.cuerpo.orbita": "Earth orbit",
      "p.cuerpo.tierra": "Earth (museum or storage)",
      "p.lugar.label": "Site or coordinates",
      "p.lugar.ph": "Oceanus Procellarum, 2.47° N 43.34° W",
      "p.estado.label": "Condition",
      "p.estado.confirmar": "To be confirmed",
      "p.estado.funciona": "Working",
      "p.estado.muerto": "Dead",
      "p.estado.recuperado": "Recovered",
      "p.resumen.label": "What it is, in one or two sentences",
      "p.resumen.ph": "A probe that landed in 1967 and stopped answering a few days later…",
      "p.fuente.label": "How do you know?",
      "p.fuente.etiqueta": "what makes the proposal verifiable",
      "p.fuente.ph": "https://science.nasa.gov/mission/…",
      "p.fuente.ayuda": "An official address (NASA, ESA, NSSDCA, a museum, a report). Without a source, the record is not accepted.",
      "p.b3.h": "Milestones for the carousel",
      "p.b3.pista": "Up to three. A short title and a sentence of 12 to 18 words, with its source. It is the same format the objects in the app use, so nothing has to be rewritten later.",
